import { getNotificationPreference } from '@/lib/notification-preference'
import { NotificationToggle } from './notification-toggle'

export default async function Home() {
  const notificationsOn = await getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are <strong>{notificationsOn ? 'on' : 'off'}</strong>.
      </p>
      <NotificationToggle enabled={notificationsOn} />
    </main>
  )
}

